-- Alt text per media-library image. One row is one image (bucket + object
-- path) with an English and an Arabic alt. Components no longer store their
-- own alt: the admin edits it once in the Insert Media modal and both the
-- cms2 preview and the public site render it everywhere the image is used.
-- Public read (the site resolves alts with the publishable key), writes
-- limited to CMS admins (public.is_admin()).

CREATE TABLE IF NOT EXISTS public.media_alt_texts (
  bucket_id text NOT NULL CHECK (char_length(bucket_id) BETWEEN 1 AND 100),
  object_path text NOT NULL CHECK (char_length(object_path) BETWEEN 1 AND 1024),
  alt_en text NOT NULL DEFAULT '' CHECK (char_length(alt_en) <= 300),
  alt_ar text NOT NULL DEFAULT '' CHECK (char_length(alt_ar) <= 300),
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (bucket_id, object_path)
);

COMMENT ON TABLE public.media_alt_texts IS
  'Shared alt text for media-library images (cms-media, destination-images), keyed by bucket + object path.';

GRANT SELECT ON public.media_alt_texts TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.media_alt_texts TO authenticated;
GRANT ALL ON public.media_alt_texts TO service_role;
ALTER TABLE public.media_alt_texts ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Media alt texts are public" ON public.media_alt_texts;
CREATE POLICY "Media alt texts are public" ON public.media_alt_texts
  FOR SELECT TO anon, authenticated
  USING (true);

DROP POLICY IF EXISTS "Admins insert media alt texts" ON public.media_alt_texts;
CREATE POLICY "Admins insert media alt texts" ON public.media_alt_texts
  FOR INSERT TO authenticated
  WITH CHECK (public.is_admin());

DROP POLICY IF EXISTS "Admins update media alt texts" ON public.media_alt_texts;
CREATE POLICY "Admins update media alt texts" ON public.media_alt_texts
  FOR UPDATE TO authenticated
  USING (public.is_admin())
  WITH CHECK (public.is_admin());

DROP POLICY IF EXISTS "Admins delete media alt texts" ON public.media_alt_texts;
CREATE POLICY "Admins delete media alt texts" ON public.media_alt_texts
  FOR DELETE TO authenticated
  USING (public.is_admin());

-- Seed: the alt each image already had on the live pages (2026-10-15). Where
-- one image carried different alts in different components, the most-used one
-- wins; alts that were just the file name are dropped (slug names become
-- plain text). Existing rows are never overwritten.
ON CONFLICT (bucket_id, object_path) DO NOTHING;
